package com.fakelegacy.customer;

import java.math.BigDecimal;

public final class TierCalculator {

    public static final BigDecimal SILVER_THRESHOLD = new BigDecimal("500");
    public static final BigDecimal GOLD_THRESHOLD = new BigDecimal("2000");

    private TierCalculator() {
    }

    public static String compute(BigDecimal revenue12m) {
        if (revenue12m.compareTo(GOLD_THRESHOLD) >= 0) {
            return "GOLD";
        }
        if (revenue12m.compareTo(SILVER_THRESHOLD) >= 0) {
            return "SILVER";
        }
        return "STANDARD";
    }

    public static int rank(String tier) {
        if ("GOLD".equals(tier)) {
            return 2;
        }
        if ("SILVER".equals(tier)) {
            return 1;
        }
        return 0;
    }
}
